slow_pseudocode:
# WRONG: grid hardcoded to old tile sizes, autotune injects different XBLOCK/YBLOCK
@triton.autotune(configs=[Config({'XBLOCK':64,'YBLOCK':32}), ...], key=[...])
@triton.jit
def kernel(...):
    ...

grid = (cdiv(xnumel, 128), cdiv(ynumel, 8))  # stale fixed grid
kernel[grid](args...)  # no XBLOCK/YBLOCK kwargs — autotune injects them but grid is wrong

fast_pseudocode:
# CORRECT: grid is a lambda that reads the autotuned tile sizes
@triton.autotune(configs=[Config({'XBLOCK':64,'YBLOCK':32}), ...], key=[...])
@triton.jit
def kernel(...):
    ...

grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']), cdiv(ynumel, meta['YBLOCK']))
kernel[grid](args...)  # autotune injects XBLOCK/YBLOCK into both kernel and grid
